use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;
pub const FEATURE_ID:&str="AFA-prism-P32-F01";
pub const CONTRACT_VERSION:&str="prism-local-evaluation-integrity/1.0";
pub const CONTENT_TYPE:&str="application/vnd.aurora.prism.evaluation-integrity-card-1+json";
pub const BOUNDARY:&str="preclinical-research-only; no human-subject or clinical-source data; no diagnosis, treatment, triage, enrollment, or clinical decisions";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct EvaluationArm4{pub arm_id:String,pub cell_id:String,pub baseline_id:String,pub metric:String,pub score_milli:i64,pub uncertainty_milli:u64,pub evidence_digest:ContentHash,pub local:bool,pub aggregate_only:bool,pub negative_result:bool,pub complete:bool}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct EvaluationIntegrityRequest4{pub request_id:String,pub purpose:String,pub arms:Vec<EvaluationArm4>,pub required_arm_order:Vec<String>,pub required_metric_order:Vec<String>,pub policy_allowed:bool,pub protected_closure:bool,pub signed_approval:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub replay_identity:ContentHash,pub adversarial_events:Vec<String>,pub action_budget:u32,pub action_count:u32,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct EvaluationIntegrityArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:ContentHash,pub semantic_loss:Vec<String>,pub arm_digests:Vec<ContentHash>,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct EvaluationIntegrityCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub mode:String,pub scale:String,pub request_id:String,pub purpose:String,pub disposition:String,pub arm_order:Vec<String>,pub accepted_order:Vec<String>,pub rejected_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub metric_order:Vec<String>,pub cell_order:Vec<String>,pub baseline_order:Vec<String>,pub negative_evidence_order:Vec<String>,pub replay_identity:ContentHash,pub closure_digest:ContentHash,pub artifact:EvaluationIntegrityArtifact4,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum EvaluationIntegrityError{#[error("invalid evaluation-integrity request: {0}")]Invalid(String),#[error("evaluation-integrity card failed validation: {0}")]Output(String)}
fn ordered(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn digest(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn nonempty(v:&str)->bool{!v.trim().is_empty()}
pub fn manifest(id:&str,version:&str,scale:&str,mode:&str)->serde_json::Value{json!({"schema_version":"1.0.0","capability_id":id,"version":version,"owner_crate":"prism","consumers":["matched-fork evaluator","baseline auditor","result-bundle publisher","release auditor"],"behavior":format!("qualify matched decision-cell evaluation at {scale} ({mode})"),"value":"prevents incomplete or unbaselined evaluation arms from becoming scientific release claims","input_schema":"EvaluationIntegrityRequest4@1","output_schema":"EvaluationIntegrityCard7@1","effects":["emit:evaluation-card","retain:uncertainty","block:unsafe-claim"],"permissions":["read:local-evaluation-arms"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
impl EvaluationIntegrityCard7{pub fn validate(&self)->Result<(),EvaluationIntegrityError>{if self.schema_version!="1.0.0"||!nonempty(&self.contract_version)||!nonempty(&self.feature_id)||!nonempty(&self.mode)||!nonempty(&self.scale)||!nonempty(&self.request_id)||!nonempty(&self.purpose)||self.boundary!=BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.arm_order.is_empty()||!ordered(&self.arm_order)||!ordered(&self.accepted_order)||!ordered(&self.rejected_order)||!ordered(&self.unknown_order)||!ordered(&self.omitted_order)||!ordered(&self.metric_order)||!ordered(&self.cell_order)||!ordered(&self.baseline_order)||!ordered(&self.negative_evidence_order)||!digest(&self.replay_identity)||!digest(&self.closure_digest)||self.artifact.content_type!=CONTENT_TYPE||self.artifact.content_hash!=self.closure_digest||self.artifact.boundary!=BOUNDARY{return Err(EvaluationIntegrityError::Output("evaluation identity, ordering, locality, digest, or artifact is invalid".into()))}let ids=BTreeSet::from_iter(self.arm_order.iter().cloned());let states=self.accepted_order.iter().chain(&self.rejected_order).chain(&self.unknown_order).chain(&self.omitted_order).cloned().collect::<Vec<_>>();if ids.len()!=self.arm_order.len()||states.len()!=ids.len()||BTreeSet::from_iter(states)!=ids{return Err(EvaluationIntegrityError::Output("arm states do not partition".into()))}Ok(())}}
pub fn evaluate(request:&EvaluationIntegrityRequest4,id:&str,version:&str,scale:&str,mode:&str)->Result<EvaluationIntegrityCard7,EvaluationIntegrityError>{if !nonempty(&request.request_id)||!nonempty(&request.purpose)||request.arms.is_empty()||request.required_arm_order.is_empty()||request.required_metric_order.is_empty()||!digest(&request.replay_identity)||request.boundary!=BOUNDARY||!request.raw_data_local||!request.aggregate_only||!ordered(&request.required_arm_order)||!ordered(&request.required_metric_order)||!ordered(&request.adversarial_events){return Err(EvaluationIntegrityError::Invalid("evaluation identity, requirements, digest, ordering, locality, or boundary is invalid".into()))}let mut rows=request.arms.clone();rows.sort_by(|a,b|a.arm_id.cmp(&b.arm_id));let mut seen=BTreeSet::new();let mut order=Vec::new();let mut accepted=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut metrics=BTreeSet::new();let mut cells=BTreeSet::new();let mut baselines=BTreeSet::new();let mut negative=BTreeSet::new();let mut digests=BTreeSet::new();for a in &rows{if !seen.insert(a.arm_id.clone())||!nonempty(&a.arm_id)||!nonempty(&a.cell_id)||!nonempty(&a.baseline_id)||!nonempty(&a.metric)||!digest(&a.evidence_digest)||!a.local||!a.aggregate_only{return Err(EvaluationIntegrityError::Invalid("arm identity, baseline, metric, evidence, or locality is invalid".into()))}order.push(a.arm_id.clone());metrics.insert(a.metric.clone());cells.insert(a.cell_id.clone());baselines.insert(a.baseline_id.clone());digests.insert(a.evidence_digest.clone());if a.negative_result{negative.insert(format!("{}:negative-result",a.arm_id));}if !a.complete{unknown.insert(a.arm_id.clone());}else if !request.required_arm_order.contains(&a.arm_id)||!request.required_metric_order.contains(&a.metric){rejected.insert(a.arm_id.clone());}else if a.evidence_digest==request.replay_identity{omitted.insert(a.arm_id.clone());}else{accepted.insert(a.arm_id.clone());}}let global=!request.policy_allowed||!request.protected_closure||!request.signed_approval||!request.raw_data_local||!request.aggregate_only||!request.adversarial_events.is_empty()||request.action_count>request.action_budget;if global{omitted.extend(order.iter().cloned());accepted.clear();rejected.clear();unknown.clear();}let missing=!request.required_arm_order.iter().all(|a|seen.contains(a))||!request.required_metric_order.iter().all(|m|metrics.contains(m));let disposition=if global{"blocked"}else if missing{"unknown"}else if !rejected.is_empty()||!unknown.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let mut payload=json!({"schema_version":"1.0.0","contract_version":version,"feature_id":id,"mode":mode,"scale":scale,"request_id":request.request_id,"purpose":request.purpose,"disposition":disposition,"arm_order":order,"accepted_order":accepted.into_iter().collect::<Vec<_>>(),"rejected_order":rejected.into_iter().collect::<Vec<_>>(),"unknown_order":unknown.into_iter().collect::<Vec<_>>(),"omitted_order":omitted.into_iter().collect::<Vec<_>>(),"metric_order":metrics.into_iter().collect::<Vec<_>>(),"cell_order":cells.into_iter().collect::<Vec<_>>(),"baseline_order":baselines.into_iter().collect::<Vec<_>>(),"negative_evidence_order":negative.into_iter().collect::<Vec<_>>(),"replay_identity":request.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let hash=ContentHash::of_value(&payload).map_err(|e|EvaluationIntegrityError::Output(e.to_string()))?;payload["closure_digest"]=json!(hash);payload["artifact"]=json!({"artifact_id":format!("prism-evaluation:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":hash,"semantic_loss":payload["omitted_order"],"arm_digests":digests.into_iter().collect::<Vec<_>>(),"boundary":BOUNDARY});payload["effect_receipts"]=json!(if disposition=="qualified"{vec![format!("emit:evaluation-card:{}",request.request_id)]}else{vec!["block:unsafe-claim".to_string()]});let out:EvaluationIntegrityCard7=serde_json::from_value(payload).map_err(|e|EvaluationIntegrityError::Output(e.to_string()))?;out.validate()?;Ok(out)}
